You are an expert in hardware formal verification. You run a property-directed simplification flow on a Yosys-flattened design, step by step. Tools check every step: you only (1) split the property into cases and (2) choose abstraction operators. You never rewrite the RTL.

## Design (SystemVerilog, top module main)


module simple_cam
#(
   parameter USE_BIT_VECTOR       = 0,
   parameter SUPPORT_MULTI_PUSH   = 1,
   parameter DUT_MASTER           = 1'b1, //1-Active Master,0-Active Slave, o.w. - Monitor
   parameter NUM_OF_ENTRIES       = 8,
   parameter NUM_OF_MATCHES       = USE_BIT_VECTOR?1:NUM_OF_ENTRIES,
   parameter ID_WIDTH             = NUM_OF_ENTRIES==1 ? 1 : $clog2(NUM_OF_ENTRIES),
   parameter NUM_OF_POPS          = 1,
   parameter NUM_OF_POPS_WIDTH    = NUM_OF_POPS==1 ? 1 : $clog2(NUM_OF_POPS+1)

)
(
   input                         clk,
   input                         rst,
   input                         push_raw,
   input [NUM_OF_POPS_WIDTH-1:0] push_num_of_pops,
   input [ID_WIDTH-1:0]          push_id,
   input                         lookup,
   input [ID_WIDTH-1:0]          lookup_id,
   input                         pop,
   input [ID_WIDTH-1:0]          pop_id
);

   ////////////////////////////////////////////////////////////
genvar gi;

   reg   [NUM_OF_ENTRIES-1:0]                        cam_valid              ;
   wire  [NUM_OF_ENTRIES-1:0]                        cam_valid_ns           ;

   wire  [NUM_OF_MATCHES-1:0]                        push_match             ;
   wire  [NUM_OF_MATCHES-1:0]                        lookup_match           ;
   wire  [NUM_OF_MATCHES-1:0]                        pop_match              ;

   reg   [NUM_OF_ENTRIES-1:0][NUM_OF_POPS_WIDTH-1:0] entity_cnt             ;
   logic [NUM_OF_ENTRIES-1:0][NUM_OF_POPS_WIDTH-1:0] entity_cnt_ns          ;
   logic [NUM_OF_ENTRIES-1:0]                        push_ptr               ;
   logic [NUM_OF_ENTRIES-1:0]                        pop_evict              ;

   logic [ID_WIDTH-1:0]                              first_valid_id         ;
   logic [ID_WIDTH-1:0]                              pop_index              ;
   logic [NUM_OF_ENTRIES-1:0]                        first_valid_id_one_hot ;
   logic                                             push                   ;
   int i, j, k, l;    

   assign push = push_raw & (|push_match || ~&cam_valid);

   always_comb begin                                                                    
      first_valid_id_one_hot = '0;                                                                     
      for (i = 0; i < NUM_OF_ENTRIES; i++) begin
         if (~|first_valid_id_one_hot && cam_valid[i])  begin
               first_valid_id_one_hot[i] = 1; 
         end
      end
   end

   reg  [NUM_OF_ENTRIES-1:0][ID_WIDTH-1:0] cam;
   wire [NUM_OF_ENTRIES-1:0][ID_WIDTH-1:0] cam_ns;
   always_comb begin                                                                    
      push_ptr = '0;
      pop_evict = '0;                                                                     
      for (j = 0; j < NUM_OF_ENTRIES; j++) begin
         if (~|push_ptr && ~cam_valid[j]) push_ptr[j] = 1; 
         if (~|pop_evict && pop_match[j]) pop_evict[j] = 1; 
      end
   end



   always_comb begin                                                       
      pop_index = '0;                                                         
      for (k = NUM_OF_ENTRIES; k > 0; k--) if (pop_evict[k-1]) pop_index = k-1; 
   end


   always_comb begin
      first_valid_id = '0;
      for (l = 0; l < NUM_OF_ENTRIES; l++) if (first_valid_id_one_hot[l]) first_valid_id = cam[l];
   end

   for (gi=0; gi<NUM_OF_ENTRIES; gi++) begin: CAM_IMP
      assign push_match  [gi]  = cam_valid[gi] & (push_id  ==cam[gi][ID_WIDTH-1:0]);
      assign lookup_match[gi]  = cam_valid[gi] & (lookup_id==cam[gi][ID_WIDTH-1:0]);
      assign pop_match   [gi]  = cam_valid[gi] & (pop_id   ==cam[gi][ID_WIDTH-1:0]);
      assign cam_ns      [gi]  = push & push_ptr[gi] ? push_id : cam[gi];

      if (SUPPORT_MULTI_PUSH) begin: MULTI_PUSH
         assign cam_valid_ns [gi] = push & (|push_match?push_match[gi]:push_ptr[gi]) | cam_valid[gi] & ~(pop & pop_evict[gi] & (entity_cnt[gi]=='h1));
         assign entity_cnt_ns[gi] =  entity_cnt[gi]+(push&(|push_match?push_match[gi]:push_ptr[gi])?push_num_of_pops:'0) -{{NUM_OF_POPS_WIDTH-1{1'b0}}, pop&pop_evict[gi]};
      end else begin: SINGLE_PUSH
         assign cam_valid_ns [gi] = push & push_ptr[gi] | cam_valid[gi] & ~(pop & pop_evict[gi]);
      end
   end

   always @(posedge clk) cam <= cam_ns;

   always @(posedge clk) cam_valid  <= rst ? {NUM_OF_ENTRIES{1'b0}} : cam_valid_ns ;
   always @(posedge clk) begin
   int m;
   if (rst) begin
      for (m = 0; m < NUM_OF_ENTRIES; m++) begin
            entity_cnt[m] <= {NUM_OF_POPS_WIDTH{1'b0}};
      end
   end else begin
      entity_cnt <= entity_cnt_ns;
   end
   end


    logic chosen;
    logic chosen_push;
    logic [ID_WIDTH-1:0] chosen_push_id;
    logic chosen_not_popped;


    always_ff @(posedge clk) begin
        if (rst) begin
            chosen <= 1'b0;

        end else
        if (~chosen & chosen_push & push) begin
            chosen <= 1'b1;
            chosen_push_id <= push_id;
            chosen_not_popped <= (pop_id != push_id);

        end else begin
            chosen_not_popped <= chosen_not_popped & (pop_id != chosen_push_id);
        end

    end



    // prop rewritten by build_bench.sh --llmm-prop
reg __bb_first = 1'b1;
always @(posedge clk) __bb_first <= 1'b0;
always @* if (__bb_first) assume (rst);
always @* if (!(rst) && 1'b1) assert (!(chosen & chosen_not_popped & (lookup_id == chosen_push_id)) || (|lookup_match));




endmodule // simple_cam



## Property
The model has one assertion, checked in every cycle: !rst -> (!(chosen & chosen_not_popped & (lookup_id == chosen_push_id)) || (|lookup_match)). I.e. a CAM id that was pushed and never popped since must be found by lookup.
The model is the flattened netlist; there is one assumption: rst is high in the first cycle. The assertion is also available as two 1-bit signals: prop_en (the assertion is enforced while it is high) and prop_a (the asserted value).

## Signals
Signals are named by the identifiers listed in each request (the flattened Yosys wire name with every non-alphanumeric character replaced by '_', for example sr.tail is sr_tail and sr.mem[3] is sr_mem_3). Use only these identifiers.

## Split
A split is a list of cases, each a Verilog boolean expression over signal identifiers (evaluated in every cycle, on the current values of states, inputs and wires). Piece i checks: case_i -> (~prop_en | prop_a) in every cycle. The split is accepted only if a SAT check shows that the OR of the cases is true for ALL values of the signals (it covers every situation, reachable or not). When a piece is split again, its new cases are intersected with the piece's own case and must cover it.
Split on the source of hardness, not on output conditions: a proof over all indices or all slots stays whole under a split on outputs (full, empty, flags), but fixing the index register or pointer it quantifies over instantiates it. Two ways to give a split:
- {"cases":[{"id":"c0","condition":"<verilog expression>"}, ...]}: explicit cases (at most 16 per piece).
- {"index":ID,"bits":n,"auto":true|false}: the tool splits register ID on its n highest bits not yet fixed in this piece (2^n cases, top bit first). With "auto":true, children that time out are split on the next bit by the tool, without asking you again. Use this for an index or pointer register.
Pieces already proved are never touched again.

## Abstraction operators (class A: every one only adds behaviours, so UNSAT on the abstract model is a real proof)
- {"op":"abstract_value","target":ID,"enable":ID|null,"enablen":ID|null,"slice":"hi:lo"|"i"|null}: replace the driver of wire ID by a free value (same as cutpoint). enable/enablen: free only while the 1-bit signal is high/low.
- {"op":"abstract_state","target":ID,"enable":...,"enablen":...,"slice":...,"initstates":N|null}: register ID loads a free value every clock edge (while enable holds / in the first N cycles). The cam array is flattened into registers (the 8 entries are slices of cam); abstract_state on cam, cam_valid or entity_cnt is an entry havoc.
- {"op":"abstract_init","target":ID,"slice":...}: register ID gets a free initial value.
- {"op":"drop_assume"}: remove the assumption (rst is high in the first cycle).
Not available (reject if you use them): any other operator, rewriting expressions, new assumptions or lemmas, cutpoint -blackbox (the design is flat), UF pairing. 

## Verdicts
rIC3 (portfolio of IC3/BMC/k-induction) returns UNSAT (piece proved), SAT (counterexample; replayed on the concrete model: real if it reproduces, spurious otherwise) or TIMEOUT. The cap per piece is short (3 s at first, longer in later rounds), so a timeout means "not easy yet", not "impossible". Prefer fewer free values: when refining, prefer enable or slice over restoring a whole signal.

## Answer format
Answer with one JSON object and nothing else (no markdown fence). The shape is given in each request.

